def _json_groups_find_range(
    groups: tuple[JsonSearchIndexGroup, ...], operator: str, threshold: Any
) -> tuple[int, ...]:
    """Merge every hit of a numeric comparison over one pointer's groups.

    Shared core of the ``lt`` / ``le`` / ``gt`` / ``ge`` leaves of
    :meth:`JsonMultiIndex.find_where`. Only the integer and float kinds
    take part — strings, booleans and null never satisfy a numeric
    comparison — and ints and floats compare by exact numeric value
    across both kinds: Python compares an int and a float by exact
    rational value without rounding the int, so big integers never
    spuriously compare equal to a nearby float threshold, and negative
    zero equals positive zero. The matching buckets' hits merge in
    strictly ascending order; range clipping is the caller's job.
    """
    if operator == "lt":

        def matches(number: Any) -> bool:
            return number < threshold

    elif operator == "le":

        def matches(number: Any) -> bool:
            return number <= threshold

    elif operator == "gt":

        def matches(number: Any) -> bool:
            return number > threshold

    else:  # "ge"

        def matches(number: Any) -> bool:
            return number >= threshold

    streams: list[tuple[int, ...]] = []
    for group in groups:
        if group.kind not in (_JSON_TAG_INTEGER, _JSON_TAG_FLOAT):
            continue
        for bucket in group.buckets:
            number = _decode_json_index_numeric(group.kind, bucket.key)
            if matches(number):
                streams.append(bucket.hits)
    merged = heapq.merge(*streams) if streams else ()
    return tuple(merged)


def _json_groups_find_prefix(
    groups: tuple[JsonSearchIndexGroup, ...], prefix: str
) -> tuple[int, ...]:
    """Merge every hit of a string-prefix match over one pointer's groups.

    Shared core of the ``prefix`` leaf of :meth:`JsonMultiIndex.find_where`.
    Only the string kind takes part — numbers, booleans and null never
    satisfy a prefix condition — and each bucket key is the UTF-8 bytes of
    one observed string, matched by plain case-sensitive
    ``str.startswith`` without any Unicode normalization, so the empty
    prefix matches every string, the empty string included. The matching
    buckets' hits merge in strictly ascending order; range clipping is the
    caller's job.
    """
    streams: list[tuple[int, ...]] = []
    for group in groups:
        if group.kind != _JSON_TAG_STRING:
            continue
        for bucket in group.buckets:
            if bucket.key.decode("utf-8").startswith(prefix):
                streams.append(bucket.hits)
    merged = heapq.merge(*streams) if streams else ()
    return tuple(merged)


def _intersect_ascending_tuples(
    left: tuple[int, ...], right: tuple[int, ...]
) -> tuple[int, ...]:
    """Intersect two strictly ascending, duplicate-free index tuples.

    Shared core of :meth:`JsonMultiIndex.find_all`; the merge walk keeps
    the result strictly ascending and duplicate free.
    """
    i = j = 0
    shared: list[int] = []
    while i < len(left) and j < len(right):
        if left[i] == right[j]:
            shared.append(left[i])
            i += 1
            j += 1
        elif left[i] < right[j]:
            i += 1
        else:
            j += 1
    return tuple(shared)


def _union_ascending_tuples(
    streams: tuple[tuple[int, ...], ...],
) -> tuple[int, ...]:
    """Union strictly ascending, duplicate-free index tuples.

    Shared core of the ``or`` combination of
    :meth:`JsonMultiIndex.find_where`; the merged walk keeps the result
    strictly ascending and drops duplicates from overlapping inputs.
    """
    merged = heapq.merge(*streams) if streams else ()
    result: list[int] = []
    for index in merged:
        if not result or result[-1] != index:
            result.append(index)
    return tuple(result)


def _complement_ascending_tuple(
    hits: tuple[int, ...], start: int, stop: int
) -> tuple[int, ...]:
    """Complement of ``hits`` within the half-open range [start, stop).

    Shared core of the ``not`` combination of
    :meth:`JsonMultiIndex.find_where`; ``hits`` must be strictly ascending
    and inside the range, and the result is strictly ascending.
    """
    result: list[int] = []
    cursor = start
    for index in hits:
        result.extend(range(cursor, index))
        cursor = index + 1
    result.extend(range(cursor, stop))
    return tuple(result)


@dataclass(frozen=True)
class JsonMultiIndex:
    """Persistent, offline-verifiable multi-pointer JSON retrieval index.

    Issued (signed) by :meth:`AuditLog.signed_json_multi_index` and
    verified entirely offline by :func:`verify_signed_json_multi_index`, it
    freezes the repeated scalar-equality lookups of
    :meth:`AuditLog.find_json` for a non-empty tuple of RFC 6901 pointers
    over the entries ``[retain_from, size)`` of the snapshot of the first
    ``size`` entries:

    - ``version``: format version, always ``1``,
    - ``hash_name``: hash algorithm of the issuing log,
    - ``size``: number of entries in the bound snapshot,
    - ``root``: Merkle root of that snapshot,
    - ``head``: chain head at that snapshot (the entry hash of its last
      record, the digest-width zero value for an empty prefix),
    - ``retain_from``: absolute index of the first covered entry,
    - ``pointers``: the non-empty tuple of canonical RFC 6901 JSON
      Pointers the index is bound to, unique and in strictly ascending
      order (the empty string addresses the whole document),
    - ``items``: every :class:`Entry` of the covered range, one per
      absolute index in strictly ascending order — exactly the indices
      ``retain_from, retain_from + 1, ..., size - 1``,
    - ``proof``: the single shared compact batch inclusion proof (as
      produced by :meth:`AuditLog.batch_inclusion_proof`) covering all of
      ``items`` within the snapshot,
    - ``groups``: one tuple of :class:`JsonSearchIndexGroup` per bound

            stop = last
        elif not isinstance(stop, int) or isinstance(stop, bool):
            raise TypeError("stop must be an integer")
        if not first <= start <= stop <= last:
            raise ValueError(
                f"range must satisfy retain_from ({first}) <= start <= stop "
                f"<= size ({last})"
            )
        return start, stop

    def find(
        self,
        pointer: Any,
        value: Any,
        start: int | None = None,
        stop: int | None = None,
    ) -> tuple[int, ...]:
        """Answer a find_json scalar-equality query from the frozen index.

        ``pointer`` must be one of the index's bound pointers (its
        canonical RFC 6901 spelling); the accepted ``value`` types, the
        JSON kind-separated comparison (strings, booleans and null match
        only their own kind; ints and floats are both JSON numbers and
        compare by numeric value), the half-open ``[start, stop)`` range
        defaults and bounds, and the strictly ascending absolute-index
        result order are exactly those of :meth:`AuditLog.find_json` over
        the index's covered snapshot. A non-``str`` or malformed pointer
        raises TypeError/ValueError as in :meth:`AuditLog.find_json`, and a
        pointer the index was not built for raises ValueError; a value of
        another type raises TypeError; a non-finite float or an
        out-of-range bound raises ValueError and a wrong bound type
        TypeError. The lookup is read-only and never mutates the index.
        """
        tokens = _parse_json_pointer(pointer)
        canonical = _json_pointer_canonical(tokens)
        try:
            position = self.pointers.index(canonical)
        except ValueError as error:
            raise ValueError(
                f"pointer {canonical!r} is not covered by this index"
            ) from error
        _check_json_value(value)
        start, stop = self._range_bounds(start, stop)
        merged = _json_groups_find_all(self.groups[position], value)
        return tuple(index for index in merged if start <= index < stop)

    def find_all(
        self,
        conditions: Any,
        start: int | None = None,
        stop: int | None = None,
    ) -> tuple[int, ...]:
        """Answer several find_json equality conditions in one lookup.

        ``conditions`` is a tuple of ``(pointer, value)`` pairs, each
        following exactly the rules of :meth:`find`: the pointer must be a
        canonical RFC 6901 spelling bound by this index and ``value`` a
        JSON scalar (``str``, ``int``, finite ``float``, ``bool`` or
        ``None``) with the same kind-separated comparison — strings,
        booleans and null match only their own kind while ints and floats
        compare by numeric value. The conditions need no ordering and a
        pointer may repeat; only entries satisfying *every* condition
        within the half-open ``[start, stop)`` range are returned, as a
        tuple of absolute indices in strictly ascending order without
        duplicates (``()`` when nothing matches). Repeating an identical
        condition never changes the result, and mutually exclusive
        conditions on one pointer yield ``()``. An empty ``conditions``
        tuple imposes no field constraint and returns every index in the
        range.

        Non-JSON, encrypted, missing-field and non-scalar targets never
        satisfy the corresponding condition, exactly as for :meth:`find`.
        A non-tuple ``conditions`` or condition, a wrong-typed pointer or
        value, or a wrong-typed range bound raises TypeError; a condition
        tuple whose length is not two, a malformed pointer, a pointer the
        index was not built for, a non-finite float, or an out-of-range or
        reversed range raises ValueError. Every condition and the range
        are validated before any lookup, so such an error is reported
        even when an earlier condition already has no hit or the range is
        empty. The lookup is read-only and never mutates the index.
        """
        if not isinstance(conditions, tuple):
            raise TypeError(
                "conditions must be a tuple of (pointer, value) pairs"
            )
        resolved: list[tuple[int, Any]] = []
        for condition in conditions:
            if not isinstance(condition, tuple):
                raise TypeError("each condition must be a (pointer, value) tuple")
            if len(condition) != 2:
                raise ValueError("each condition must have exactly two items")
            pointer, value = condition
            tokens = _parse_json_pointer(pointer)
            canonical = _json_pointer_canonical(tokens)
            try:
                position = self.pointers.index(canonical)
            except ValueError as error:
                raise ValueError(
                    f"pointer {canonical!r} is not covered by this index"
                ) from error
            _check_json_value(value)
            resolved.append((position, value))
        start, stop = self._range_bounds(start, stop)
        if not resolved:
            return tuple(range(start, stop))
        result: tuple[int, ...] | None = None
        for position, value in resolved:
            merged = _json_groups_find_all(self.groups[position], value)
            hits = tuple(index for index in merged if start <= index < stop)
            if result is None:
                result = hits
            else:
                result = _intersect_ascending_tuples(result, hits)
            if not result:
                break
        return tuple(() if result is None else result)

    def _resolve_where_expression(self, expression: Any) -> tuple:
        """Validate a :meth:`find_where` expression and resolve pointers.

        Returns a parallel tree with every leaf pointer replaced by its
        position in ``self.pointers``. Validation is pre-order: a node's
        own errors are reported before its children's, and children are
        checked from left to right.
        """
        if not isinstance(expression, tuple):
            raise TypeError("expression nodes must be tuples")
        if not expression:
            raise ValueError("expression node must not be empty")
        operator = expression[0]
        if not isinstance(operator, str):
            raise TypeError("expression operator must be a string")
        if operator == "eq":
            if len(expression) != 3:
                raise ValueError('an "eq" node must have exactly three items')
            _, pointer, value = expression
            tokens = _parse_json_pointer(pointer)
            canonical = _json_pointer_canonical(tokens)
            try:
                position = self.pointers.index(canonical)
            except ValueError as error:
                raise ValueError(
                    f"pointer {canonical!r} is not covered by this index"
                ) from error
            _check_json_value(value)
            return ("eq", position, value)
        if operator == "in":
            if len(expression) != 3:
                raise ValueError('an "in" node must have exactly three items')
            _, pointer, values = expression
            tokens = _parse_json_pointer(pointer)
            canonical = _json_pointer_canonical(tokens)
            try:
                position = self.pointers.index(canonical)
            except ValueError as error:
                raise ValueError(
                    f"pointer {canonical!r} is not covered by this index"
                ) from error
            if not isinstance(values, tuple):
                raise TypeError('"in" values must be a tuple of scalars')
            for value in values:
                _check_json_value(value)
            return ("in", position, values)
        if operator in ("lt", "le", "gt", "ge"):
            if len(expression) != 3:
                raise ValueError(
                    f'a "{operator}" node must have exactly three items'
                )
            _, pointer, threshold = expression
            tokens = _parse_json_pointer(pointer)
            canonical = _json_pointer_canonical(tokens)
            try:
                position = self.pointers.index(canonical)
            except ValueError as error:
                raise ValueError(
                    f"pointer {canonical!r} is not covered by this index"
                ) from error
            _check_json_threshold(threshold)
            return (operator, position, threshold)
        if operator == "prefix":
            if len(expression) != 3:
                raise ValueError(
                    'a "prefix" node must have exactly three items'
                )
            _, pointer, text = expression
            tokens = _parse_json_pointer(pointer)
            canonical = _json_pointer_canonical(tokens)
            try:
                position = self.pointers.index(canonical)
            except ValueError as error:
                raise ValueError(
                    f"pointer {canonical!r} is not covered by this index"
                ) from error
            if not isinstance(text, str):
                raise TypeError("prefix text must be a string")
            return ("prefix", position, text)
        if operator == "exists":
            if len(expression) != 2:
                raise ValueError(
                    'an "exists" node must have exactly two items'
                )
            _, pointer = expression
            tokens = _parse_json_pointer(pointer)
            canonical = _json_pointer_canonical(tokens)
            try:
                position = self.pointers.index(canonical)
            except ValueError as error:
                raise ValueError(
                    f"pointer {canonical!r} is not covered by this index"
                ) from error
            return ("exists", position)
        if operator in ("and", "or"):
            if len(expression) != 2:
                raise ValueError(
                    f'an "{operator}" node must have exactly two items'
                )
            children = expression[1]
            if not isinstance(children, tuple):
                raise TypeError(f'"{operator}" children must be a tuple')
            return (
                operator,
                tuple(
                    self._resolve_where_expression(child) for child in children
                ),
            )
        if operator == "not":
            if len(expression) != 2:
                raise ValueError('"not" node must have exactly two items')
            return ("not", self._resolve_where_expression(expression[1]))
        raise ValueError(f"unknown expression operator {operator!r}")

    def _evaluate_where_expression(
        self, node: tuple, start: int, stop: int
    ) -> tuple[int, ...]:
        """Evaluate a resolved :meth:`find_where` tree over [start, stop)."""
        operator = node[0]
        if operator == "eq":
            merged = _json_groups_find_all(self.groups[node[1]], node[2])
            return tuple(index for index in merged if start <= index < stop)
        if operator == "in":
            merged = _union_ascending_tuples(
                tuple(
                    _json_groups_find_all(self.groups[node[1]], value)
                    for value in node[2]
                )
            )
            return tuple(index for index in merged if start <= index < stop)
        if operator in ("lt", "le", "gt", "ge"):
            merged = _json_groups_find_range(
                self.groups[node[1]], operator, node[2]
            )
            return tuple(index for index in merged if start <= index < stop)
        if operator == "prefix":
            merged = _json_groups_find_prefix(self.groups[node[1]], node[2])
            return tuple(index for index in merged if start <= index < stop)
        if operator == "exists":
            return self._exists_hits(node[1], start, stop)
        if operator == "and":
            children = node[1]
            if not children:
                return tuple(range(start, stop))
            result: tuple[int, ...] | None = None
            for child in children:
                hits = self._evaluate_where_expression(child, start, stop)
                if result is None:
                    result = hits
                else:
                    result = _intersect_ascending_tuples(result, hits)
                if not result:
                    break
            return tuple(() if result is None else result)
        if operator == "or":
            return _union_ascending_tuples(
                tuple(
                    self._evaluate_where_expression(child, start, stop)
                    for child in node[1]
                )
            )
        # "not": complement over every index of the query range.
        hits = self._evaluate_where_expression(node[1], start, stop)
        return _complement_ascending_tuple(hits, start, stop)

    def _exists_hits(self, position: int, start: int, stop: int) -> tuple[int, ...]:
        """Evaluate a resolved ``exists`` leaf over [start, stop).

        Walks the frozen covered entries in ascending order and reports
        every index whose payload is strict UTF-8 JSON (no repeated
        member name) in which the bound pointer resolves to any value —
        null, a scalar, an object or an array. An AES-256-GCM envelope
        and every parse failure simply do not hit; neither raises.
        """
        tokens = _parse_json_pointer(self.pointers[position])
        hits: list[int] = []
        for entry in self.items:
            if entry.index < start:
                continue
            if entry.index >= stop:
                break
            payload = entry.payload
            if payload.startswith(_ENC_MAGIC):
                # An AES-256-GCM envelope is never plain JSON; it takes
                # no part and never reaches the parser.
                continue
            document = _strict_json_document(payload)
            if document is _JSON_MISSING:
                continue
            if _json_pointer_exists(document, tokens):
                hits.append(entry.index)
        return tuple(hits)

    def find_where(
        self,
        expression: Any,
        start: int | None = None,
        stop: int | None = None,
    ) -> tuple[int, ...]:
        """Answer a nested boolean query of find_json equality leaves.

        ``expression`` is a tuple tree. A leaf is ``("eq", pointer,
        value)`` and follows exactly the rules of :meth:`find`: the
        pointer must be a canonical RFC 6901 spelling bound by this index
        and ``value`` a JSON scalar (``str``, ``int``, finite ``float``,
        ``bool`` or ``None``) with the same kind-separated comparison —
        strings, booleans and null match only their own kind while ints
        and floats compare by numeric value. A set-membership leaf is
        ``("in", pointer, values)`` with the same pointer rules;
        ``values`` is a tuple of candidate scalars, each following
        exactly the ``eq`` value rules, and an entry matches when its
        addressed scalar equals any one candidate — repeated candidates
        never add duplicate hits and an empty candidate tuple matches
        nothing. A numeric-comparison leaf is
        ``("lt", pointer, threshold)``, ``("le", pointer, threshold)``,
        ``("gt", pointer, threshold)`` or ``("ge", pointer, threshold)``
        with the same pointer rules; ``threshold`` must be a non-boolean
        ``int`` or a finite ``float`` and the addressed JSON number
        compares against it by exact numeric value across the integer
        and float kinds — big integers never round to a nearby float and
        negative zero equals positive zero. A string-prefix leaf is
        ``("prefix", pointer, text)`` with the same pointer rules;
        ``text`` must be a ``str`` and only an addressed JSON string
        that starts with it matches — case-sensitively and without any
        Unicode normalization — so the empty prefix matches every
        string, the empty string included. A field-existence leaf is
        ``("exists", pointer)`` with the same pointer rules; it matches
        every entry whose payload is strict UTF-8 JSON (no repeated
        member name) in which the pointer resolves to any value at all
        — null, a scalar, an object or an array — so a missing field
        and a field explicitly set to ``null`` are told apart, the
        empty pointer matches every valid JSON document (the empty
        object and the empty array included), and an out-of-range,
        leading-zero or append-position array token or a path through a
        scalar does not hit. A combination is
        ``("and", children)``, ``("or", children)`` or ``("not", child)``
        where ``children`` is a tuple of sub-expressions that may nest
        recursively. ``and`` intersects its children's hits, ``or`` takes
        their union and ``not`` complements its child against every index
        of the query range. An empty ``and`` returns the whole range, an
        empty ``or`` returns ``()``, a double negation restores the
        original hits and repeating a branch never adds duplicate hits.
        The result is a tuple of absolute indices in strictly ascending
        order without duplicates (``()`` when nothing matches), clipped
        to the half-open ``[start, stop)`` range with the same defaults
        and bounds as :meth:`find`; an empty range yields ``()``.

        Non-JSON, encrypted, missing-field and non-scalar targets never
        satisfy an ``eq`` or ``in`` leaf — a missing field is not
        ``null`` — and
        non-numeric targets (booleans, strings, null, objects and arrays)
        never satisfy a numeric-comparison leaf, just as non-string
        targets never satisfy a ``prefix`` leaf, so all of them do
        satisfy that leaf's negation, exactly as for :meth:`find`.
        Invalid UTF-8, invalid JSON, a repeated member name and an
        encrypted entry never satisfy an ``exists`` leaf either — the
        parse failure is not a query error — so they satisfy its
        negation. A
        non-tuple node or ``children``, a non-string operator or pointer,
        a value or threshold of another type, a non-string prefix text,
        a non-tuple ``in`` candidate container or a candidate of another
        type,
        or a wrong-typed range bound raises TypeError; an empty node, an
        unknown operator, a node of the wrong length, a malformed or
        uncovered pointer, a non-finite float value, threshold or ``in``
        candidate, or an
        out-of-range or reversed range raises ValueError. The whole expression is
        validated before any lookup — a node's own errors before its
        children's, children from left to right, an ``in`` node's length
        and pointer before its candidate container and each candidate in
        order, the range last — so an
        empty range, an empty candidate tuple or an already determined
        intermediate result never
        masks an invalid branch. The lookup is read-only and never
        mutates the index.
        """
        resolved = self._resolve_where_expression(expression)
        start, stop = self._range_bounds(start, stop)
        return self._evaluate_where_expression(resolved, start, stop)


@dataclass(frozen=True)
class SignedJsonMultiIndex:
    """Persistent multi-pointer JSON index sealed by a trusted Ed25519 key.

    Bundles the :class:`JsonMultiIndex` of
    :meth:`AuditLog.signed_json_multi_index` with a 64-byte Ed25519
    signature over a domain-separated message embedding the index's whole
    canonical encoding (:func:`encode_json_multi_index`), so the
    signature binds the ordered pointer tuple, the hash algorithm,
    snapshot ``size``, Merkle root, chain head, retain point, the complete
    covered entry set, the shared proof and every pointer's hit sets. An
    offline receiver holding only a pre-trusted 32-byte Ed25519 public key
    confirms coverage, the complete hit sets and the signature with
    :func:`verify_signed_json_multi_index` — no :class:`AuditLog`
    required — then answers repeated :meth:`find` queries offline.

    Instances are immutable, may be built positionally and compare by both
    fields. ``index`` must be a :class:`JsonMultiIndex` and ``signature``
    exact 64-byte ``bytes`` (``bytearray`` / ``memoryview`` are rejected);
    whether the signature is genuine is left to
    :func:`verify_signed_json_multi_index`.
    """

_JSON_MISSING = object()

# Scalar kinds that may appear in a JsonSearchIndex group.
_JSON_INDEX_KINDS = frozenset(
    {
        _JSON_TAG_STRING,
        _JSON_TAG_INTEGER,
        _JSON_TAG_FLOAT,
        _JSON_TAG_TRUE,
        _JSON_TAG_NULL,
        _JSON_TAG_FALSE,
    }
)

# Kinds whose single value is encoded as the empty blob (true / false / null).
_JSON_INDEX_EMPTY_KINDS = frozenset(
    {_JSON_TAG_TRUE, _JSON_TAG_FALSE, _JSON_TAG_NULL}
)


class _JsonDuplicateMember(ValueError):
    """Internal: a JSON object repeated a member name."""


def _decode_json_index_numeric(kind: int, key: bytes) -> Any:
    """Decode a canonical integer/float bucket key back to its number.

    Structural validity (ASCII, finite) is enforced by
    :func:`_check_json_index_bucket_key`; this only re-parses.
    """
    if kind == _JSON_TAG_INTEGER:
        return int(key.decode("ascii"))
    return float(key.decode("ascii"))


def _check_json_index_bucket_key(kind: int, key: Any) -> None:
    """Validate one bucket key blob for its group's kind."""
    if not isinstance(key, bytes):
        raise TypeError("bucket key must be bytes")
    if kind in _JSON_INDEX_EMPTY_KINDS:
        if key:
            raise ValueError(
                "a boolean or null bucket key must be the empty blob"
            )
        return
    if kind == _JSON_TAG_STRING:
        # Strings carry arbitrary text; the key must be valid UTF-8.
        try:
            key.decode("utf-8")
        except UnicodeDecodeError as error:
            raise ValueError("string bucket key must be valid UTF-8") from error
        return
    try:
        text = key.decode("ascii")
    except UnicodeDecodeError as error:
        raise ValueError("numeric bucket key must be ASCII") from error
    if kind == _JSON_TAG_INTEGER:
        digits = text[1:] if text[:1] == "-" else text
        if not digits or any(ch not in "0123456789" for ch in digits):
            raise ValueError("integer bucket key must be canonical ASCII decimal")
    elif kind == _JSON_TAG_FLOAT:
        try:
            value = float(text)
        except ValueError as error:
            raise ValueError("float bucket key must be an ASCII number") from error
        if not math.isfinite(value):
            raise ValueError("float bucket key must be finite")
        if repr(value).encode("ascii") != key:
            raise ValueError("float bucket key must be the canonical repr spelling")


def _check_json_value(value: Any) -> None:
    """Validate a find_json / json_search_receipt scalar query value."""
    if isinstance(value, bool) or isinstance(value, str) or value is None:
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("value must be a finite number")
        return
    raise TypeError("value must be str, int, float, bool or None")


def _check_json_threshold(value: Any) -> None:
    """Validate a find_where numeric-comparison threshold.

    Only a non-boolean ``int`` or a finite ``float`` is accepted: booleans
    are not numbers for this comparison, and a non-finite threshold would
    make the comparison degenerate.
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("threshold must be an int or a float")
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError("threshold must be a finite number")


def _parse_json_pointer(pointer: Any) -> tuple[str, ...]:
